-- Manuscript index: books, chapters, scenes, passages.
-- The Markdown files in each book's Git repository are the only copy of the prose; these tables
-- are a rebuildable index of structure and stable identifiers. No prose is stored here.
-- IDs are short random text identifiers generated by the server (e.g. bk_, ch_, sc_ prefixes; passages
-- use the bare 8-character id that also appears in the Markdown marker).

CREATE TABLE books (
    id          TEXT PRIMARY KEY NOT NULL,
    title       TEXT NOT NULL CHECK (length(title) BETWEEN 1 AND 300),
    language    TEXT NOT NULL CHECK (language IN ('ru', 'en')),
    head_commit TEXT,                              -- Git commit the index was last synchronised with
    created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
) STRICT;

CREATE TABLE chapters (
    id          TEXT PRIMARY KEY NOT NULL,
    book_id     TEXT NOT NULL REFERENCES books (id),
    position    INTEGER NOT NULL CHECK (position >= 0),
    title       TEXT NOT NULL DEFAULT '',
    path        TEXT NOT NULL CHECK (length(path) > 0),   -- repository-relative path of the chapter file
    created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    UNIQUE (book_id, path)
) STRICT;
CREATE INDEX chapters_by_book ON chapters (book_id, position);

CREATE TABLE scenes (
    id          TEXT PRIMARY KEY NOT NULL,
    book_id     TEXT NOT NULL REFERENCES books (id),
    chapter_id  TEXT NOT NULL REFERENCES chapters (id),
    position    INTEGER NOT NULL CHECK (position >= 0),
    title       TEXT NOT NULL DEFAULT '',
    path        TEXT NOT NULL CHECK (length(path) > 0),   -- repository-relative path of the scene file
    language    TEXT NOT NULL CHECK (language IN ('ru', 'en')),
    pov         TEXT,                                     -- front-matter values, as the author wrote them
    story_date  TEXT,
    location    TEXT,
    created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    UNIQUE (book_id, path)
) STRICT;
CREATE INDEX scenes_by_chapter ON scenes (chapter_id, position);

-- A passage is one paragraph. Passages are never deleted: a removed or merged passage stays as a
-- tombstone so that evidence links can find it and be flagged instead of silently dangling.
CREATE TABLE passages (
    id          TEXT PRIMARY KEY NOT NULL,
    book_id     TEXT NOT NULL REFERENCES books (id),
    scene_id    TEXT NOT NULL REFERENCES scenes (id),     -- may change when a paragraph moves to another scene
    position    INTEGER NOT NULL CHECK (position >= 0),
    text_hash   TEXT NOT NULL CHECK (length(text_hash) = 64),   -- SHA-256 (hex) of the normalised paragraph text
    status      TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'removed')),
    removed_at  TEXT,
    merged_into TEXT REFERENCES passages (id),            -- set when the passage was merged into another one
    created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    CHECK (status = 'active' OR removed_at IS NOT NULL),
    CHECK (merged_into IS NULL OR status = 'removed')
) STRICT;
CREATE INDEX passages_by_scene ON passages (scene_id, status, position);
CREATE INDEX passages_by_book ON passages (book_id, status);
